// Сгенерировано tools/build-base-media.mts: описания карточек справочника (TMDb), доля 04 из 16 по id
// (src/lib/shard.ts) — подгружается, когда раскрывают «Сюжет» (src/api, getPlot). Не править руками.
export const blurbs: Record<string, string> = {
 "f-wd125908027": "Только один человек обладает особым набором навыков, чтобы возглавить полицейский отряд и спасти мир: лейтенант Фрэнк Дребин-младший.",
 "f-wd56816969": "На этот раз необходимость расследовать загадочное убийство, отвлекаясь от собственного отдыха, настигает Пуаро на борту роскошного круизного парохода, следующего вдоль по Нилу.",
 "f-wd80322391": "Продолжение саги, начатой в «Матрице», стирающее грань между бытием и иллюзией. Нео и Тринити возвращаются, но не как воспоминания, не как призраки прошлого, а как сила, способная изменить саму ткань реальности. Мир, в который они возвращаются, наполнен знакомыми образами, но искажает их, как отражение в треснувшем зеркале. Здесь реальность не фиксирована — она дышит, подстраивается под героев. Чтобы увидеть истину, недостаточно выбрать таблетку. Нужно перестать верить в саму возможность выбора. Потому что теперь всё, что остаётся, — это довериться падению.",
 "f-wd18406872": "Страшная автокатастрофа поставила крест на карьере успешного нейрохирурга Доктора Стрэнджа. Отчаявшись, он отправляется в путешествие в поисках исцеления и открывает в себе невероятные способности к трансформации пространства и времени. Теперь он — связующее звено между параллельными измерениями, а его миссия — защищать жителей Земли и противодействовать Злу, какое бы обличие оно ни принимало.",
 "f-wd172271": "Юная волшебница Малефисента вела уединенную жизнь в зачарованном лесу, окруженная сказочными существами, но однажды все изменилось... В её мир вторглись люди, которые принесли с собой разрушение и хаос, и Малефисенте пришлось встать на защиту своих подданных, призвав на помощь могущественные тёмные силы. В пылу борьбы Малефисента наложила страшное заклятие на новорожденную дочь короля, прекрасную Аврору. Но, наблюдая за тем, как растет маленькая принцесса, Малефисента начинает сомневаться в правильности своего поступка - ведь, возможно, именно Аврора может вдохнуть новую жизнь в волшебное лесное царство.",
 "f-wd2528155": "Анатолий Ефремович Новосельцев занимает рядовую должность в Статистическом управлении, в одиночку воспитывает двоих маленьких сыновей, дружит с коллегой по имени Ольга и... до потери сознания боится собственную начальницу — директора Людмилу Прокофьевну Калугину. Невероятный служебный роман начинается по совету Самохвалова, нового заместителя последней и старого институтского товарища Новосельцева, который подал идею продвинуться таким образом по карьерной лестнице.",
 "f-wd3522637": "Кто сказал, что в сердце маленького человека не могут жить великие мечты? Даже скромному и незаметному служащему хочется иногда совершить пусть безумные, но геройские поступки, поверить в свою силу и мужество. Почему всех спасать должны исключительно супермены?",
 "f-wd130590402": "Чарли и Эмма познакомились в кафе два года назад, а через неделю должны пожениться. Они активно готовятся к торжеству: репетируют свадебный танец, общаются с диджеем и фотографом и выбирают напитки на праздничный стол. Однажды за ужином с друзьями Эмма раскрывает неожиданный секрет своего прошлого, и это откровение вынуждает Чарли задуматься, знает ли он её на самом деле.",
 "f-wd126488898": "Роскошные особняки, частные самолёты и даже собственные острова — состояние клана Редфеллоу исчисляется миллиардами. Всё это мечтает унаследовать Беккет, хоть глава рода и отрёкся от него ещё до его рождения. Однако на пути к заветной жизни стоят семь избалованных богачей. Чтобы ускорить свою очередь на наследство, Беккету придётся «спилить» несколько ветвей семейного древа. И сделать это так дерзко и изобретательно, чтобы избежать наказания за убийства.",
 "f-wd131630491": "Милли устраивается прислугой с проживанием к состоятельной семье Винчестер, живущей в загородном особняке. Девушка только что вышла по УДО, и ей необходима эта работа, но находить общий язык с хозяйкой Ниной становится всё сложнее: та заметно не в себе и регулярно к ней цепляется. Зато её супруг Эндрю - само очарование. Мужчина сглаживает любые конфликты и, кажется, положил глаз на Милли.",
 "f-wd121433282": "Май 2020 года, в США набирает обороты пандемия. В тихом провинциальном Эддингтоне, где объявлен карантин и введён масочный режим, назревает противостояние между шерифом округа Севилья Джо Кроссом и мэром города Тэдом Гарсией, который планирует переизбираться и задумывает грандиозный проект — возведение масштабного центра по обработке данных на базе искусственного интеллекта. Не желая мириться с планами властного чиновника, Кросс решает бросить ему вызов и выдвигает свою кандидатуру на пост мэра, не подозревая к каким непредсказуемым последствиям приведёт его решение.",
 "f-wd125472432": "Однажды к папе Карло попадает древний волшебный ключ, который помогает исполнить любое желание. Одинокий мастер хочет только одного — сына. Желание уже почти исполнилось, но полено оживает, из него появляется умный, веселый и деревянный мальчик. Папа Карло очень любит сына, но Буратино постепенно понимает, что он не такой, как все, и отправляется в длинное и полное приключений путешествие, чтобы доказать папе: он хороший и настоящий сын.",
 "f-wd116315647": "Группа канадских разработчиков ставит на кон абсолютно всё ради безумной идеи объединить компьютер и телефон в одном устройстве. Так рождается первый в мире смартфон BlackBerry, который в одночасье завоёвывает весь рынок и делает своих создателей миллиардерами. Но, чтобы удержаться на этой высоте, недостаточно быть гениями технологий. Новая реальность и безжалостная конкуренция Кремниевой Долины бросает вызов героям, испытывая их веру в себя и отношения друг с другом...",
 "f-wd14772351": "Опасаясь, что действия богоподобного супергероя так и останутся бесконтрольными, грозный и могущественный страж Готэм Сити бросает вызов самому почитаемому в наши дни спасителю Метрополиса, в то время как весь остальной мир решает, какой герой ему по-настоящему нужен. И пока Бэтмен и Супермен пребывают в состоянии войны друг с другом, возникает новая угроза, которая ставит человечество под самую большую опасность, с которой оно когда-либо сталкивалось.",
 "f-wd113012523": "Молодой официантке Фриде из Лос-Анджелеса, удается попасть в окружение филантропа и IT-магната Слейтера Кинга. Девушка посещает вечеринки и знакомится с новыми людьми на частном острове бизнесмена, однако со временем понимает, что здесь творится что-то неладное.",
 "f-wd2083023": "Тема фильма — отношения между армейскими офицерами в условиях закрытого общества военной части. Два главных героя — младшие офицеры, находящиеся на гауптвахте, сидя в одной камере, вынуждены решать острые социальные и психологические проблемы на небольшом пространстве. Реалистичность диалогов и декораций взрывается внутренним абсурдом поступков и брутальностью мотиваций персонажей.",
 "f-wd65768604": "Джейн Фостер берет на себя обязанности Бога-громовержца и становится обладательницей молота Мьёльнира.",
 "f-wd28657013": "Спустя почти 5 000 лет после того, как он был наделен всемогущими силами египетских богов и так же быстро заключен в тюрьму, Черный Адам освобождается из своей земной гробницы и готов обрушить свою уникальную форму правосудия на современный мир.",
 "f-wd105549749": "Милан, 1978 год. Девушка из небогатой семьи Патриция Реджани на вечеринке знакомится с Маурицио Гуччи, нерешительным наследником знаменитого модного дома. Несмотря на неодобрение его отца Родольфо и отлучение от финансирования, молодые люди женятся. Но дядя Маурицио, второй владелец империи Альдо Гуччи, хочет наладить семейные отношения, и Патриция, пользуясь советами и наущениями телевизионной гадалки, решает извлечь из этой ситуации максимальную выгоду.",
 "f-wd19946102": "Обозлённая Волшебница превратила принца Адама в отвратительное чудовище за то, что тот был злым, самовлюблённым и грубым. Чтобы снять чары с себя и слуг своего замка, ему необходимо научиться быть добрым, любить и быть любимым. Произойти это должно до того, как с розы, подаренной Волшебницей, упадёт последний лепесток.  В далёкой деревушке живёт красивая девушка по имени Белль. Однажды её отец Морис отправляется на ярмарку, но по дороге сбивается с пути. Оказавшись в заколдованном замке, он становится пленником Чудовища. Белль спешит отцу на помощь.",
 "f-wd12049257": "Раккун-Сити становится последним рубежом в борьбе человечества с вирусом, превратившим мир в царство заражённых. Элис возвращается туда, где всё началось, чтобы найти способ уничтожить вирус и раз и навсегда остановить корпорацию «Амбрелла». На пути к цели ей предстоит пробиться через орды зомби, мутировавших существ и смертельно опасные ловушки подземного комплекса. В финальном противостоянии Элис раскрывает тайны своего прошлого и узнаёт правду, которая способна изменить всё, что она знала о себе и происхождении вируса.",
 "f-wd18647981": "Действие происходит 2000 лет назад, в островах Тихого океана. Дочка вождя, 14-летняя мечтательница Моана Ваялики, чтобы найти свою семью, отправляется в путешествие по океану в поисках сказочного острова с её героем полубогом-трикстером Мауи, и вместе им предстоит переплыть океан, встречая по пути огромных морских существ.",
 "f-wd17030810": "Действие будет разворачиваться в супермаркете, где сосискам нужно будет срочно выбраться на волю, пока не наступил День Независимости.",
 "f-wd15209986": "В футуристическом обществе, где полиция из несокрушимых роботов держит преступность в узде, одинокий дроид переходит на новую ступень эволюции.",
 "f-wd720357": "Харриган - крутой полицейский отдела по борьбе с наркотиками полиции Лос-Анджелеса. Ему поручено расследование серии убийств крупных криминальных авторитетов города. Все убийства совершены в извращенной форме и пахнут неприкрытым садизмом. После проведения экспертиз и расследований становится ясно, что убийство - дело рук существа, не имеющего ничего общего с человеком. Землю опять посетил межпланетный охотник, но ему придется столкнуться с существом еще более опасным, чем он сам - с человеком.",
 "f-wd822426": "Рядовой клерк Йозеф К. обвиняется в некоем преступлении, которое он не совершал, поскольку не совершал вообще ничего противозаконного. Собственно, состав преступления ему не называют и сами обвинители, поскольку так же не знают, в чём он виноват…",
 "f-wd4407197": "Всего один легкомысленный поступок может привести к тому, что собственную свадьбу придется праздновать на небесах. Вадик даже не догадывался, что, желая сделать праздник веселее, он попадет в Чистилище, где предстанет перед Небесной канцелярией и будет отчитываться за всю свою короткую, но насыщенную жизнь. Как доказать богам, что ты хороший, если у них записан каждый твой шаг?",
 "f-wd115860236": "1942 год, Великобритания. Они - лучшие из лучших. Отпетые авантюристы и первоклассные спецы, привыкшие действовать в одиночку. Но когда на кону стоит судьба всего мира, им приходится объединиться в сверхсекретное боевое подразделение и отправиться на выполнение дерзкой миссии против нацистов. Теперь их дело - война, и вести они её будут совершенно не по-джентльменски.",
 "f-wd123861757": "Глава крупной компании, привыкшая управлять людьми, становится игрушкой молодого интерна. Правила просты. Она подчиняется всем его приказам, а он хранит ее тайну. Но вырвавшаяся за пределы офиса страсть грозит уничтожить их обоих.",
 "f-wd118212751": "Уже два месяца студентке Стефани снится один и тот же страшный сон, как в 1960-ых люди гибнут при обрушении телебашни. Подозревая, что этот кошмар связан с её семьёй, девушка возвращается домой, чтобы разузнать о бабушке, с которой её родители и дядя с тётей давно порвали все связи, поскольку считают её опасной сумасшедшей, одержимой идеей смерти.",
 "f-wd118904382": "Подростку Иккингу не слишком близки традиции его героического племени, много лет ведущего войну с драконами. Парень неожиданно заводит дружбу с драконом Беззубиком, который поможет ему и другим викингам увидеть мир с совершенно другой стороны.",
 "f-wd106329715": "Вселенски известная охотница за головами Лилит получает задание отправиться на планету Пандора, где прошло её трудное детство, и вызволить из заточения похищенную бандитами дочку межгалактического бизнесмена Атласа. На месте выясняется, что девочку никто против воли не удерживает, и она весело проводит время в сомнительной компании, а также все считают её Избранной, способной открыть некое легендарное Хранилище.",
 "f-wd19329909": "Весна 1917-го года. Февральская революция изменила жизнь России и ход Великой войны. Государь уже отрёкся от престола. В окопах, где противостояние с немцами длится уже не один год, во всю вели свою пропаганду большевики. Они призывают к миру с неприятелем. Российское офицерство фактически ничего не может решить без одобрения так называемых солдатских комитетов. Армия находится на пороге окончательного разложения.  По приказу временного правительства для поднятия боевого духа создаётся женский «Батальон смерти» под командованием георгиевского кавалера Марии Бочкарёвой. Своей службой «Батальон смерти» подаёт пример храбрости, мужества и спокойствия, поднимает дух солдат и доказывает, что каждая из этих женщин-героев достойна звания воина русской армии.",
 "f-wd114876737": "Санта-Клаус под кодовым именем Красный похищен. Начальник службы безопасности Северного полюса должен объединиться с самым известным в мире охотником за головами. Вместе они начинают кругосветную миссию по спасению Рождества.",
 "f-wd112811482": "Брак молодой женщины со сказочным принцем превращается в жестокую битву за жизнь, когда ее решают принести в жертву огнедышащему дракону.",
 "f-wd119549900": "Участвующий в судебном разбирательстве присяжный, понимая свою причастность к преступлению, стоит перед очень непростым выбором: ему нужно либо отдаться в руки закона, либо продолжать манипулировать и обманывать своих коллег. Весы все сильнее склоняются ко второму варианту...",
 "f-wd124353875": "После удачного, хотя и не без сложностей, ограбления профессиональный вор Паркер и его команда готовятся делить добычу. Внезапно один из грабителей, девушка Зен, расстреливает группу, а Паркер, получив ранение, чудом выживает. Залечив раны, вор с кодексом чести, потерявший команду и лучшего друга, решает разобраться с предательницей и вернуть похищенные ею 400 тысяч долларов. Однако при встрече с Зен выясняется, что все деньги уже потрачены на планирование крупного ограбления с призовым фондом в сотни миллионов долларов. Зен уговаривает Паркера стать частью плана, и тот нехотя соглашается.",
 "f-wd64017": "Хизер терзается ночными кошмарами с одиннадцатилетнего возраста и вынуждена со своим отцом постоянно менять место жительства, скрываясь от таинственных сил. Накануне своего восемнадцатого дня рождения Хизер, вернувшись домой, обнаруживает, что её отец исчез. Единственное, что она нашла дома — нарисованный на стене оккультный символ с надписью «отправляйся в Сайлент Хилл».",
 "f-wd125371155": "Стефани стала частным детективом и писательницей, раскрыв преступление и отправив в тюрьму подругу Эмили. Но спустя 5 лет женщина неожиданно выходит на свободу и вновь появляется в жизни Стефани — она приглашает писательницу на свою роскошную свадьбу на острове Капри.",
 "f-wd61876370": "Итан Хант и его команда противостоят системе искусственного интеллекта Entity, которая вышла из под контроля и стала угрозой человечества.",
 "f-wd104641226": "Иван наконец обрел силушку богатырскую, злой чародей Роголеб повержен, и теперь все Белогорье готовится к пиру на весь мир: Иван и Василиса собираются праздновать свадьбу, решая типичные для почти любой пары молодоженов проблемы. В каком платье пойти под венец невесте? Кольца — простые или волшебные? Свадебное путешествие — на куриных ногах или в ступе? В самый разгар приготовлений к празднику зло снова напоминает о себе: Василиса похищена, и в пылу погони Иван и его друзья оказываются в современной Москве. Для жителей Белогорья это — волшебный мир, в котором люди перемещаются на странных колесницах, разговаривают с плоскими дощечками и не в состоянии отличить настоящую магию от дешевой детской игрушки. Но, как выясняется, и в этом мире, бок о бок с обычными людьми, неплохо устроились герои старых сказок, и с их помощью у Ивана есть шанс окончательно победить древнюю Тьму.",
 "f-wd40895": "История о маленьком слоненке из цирка, родившемся с очень большими ушами, что было рассмотрено как позорное явление среди цирковых слонов. Но зато он научился летать.",
 "f-wd188474": "Полная опасностей жизнь на Мадагаскаре не оправдала ожиданий привыкших к комфорту Нью-Йоркского зоопарка животных — льва Алекса, зебры Марти, жирафа Мелмана и бегемотихи Глории — и друзья решают сбежать с острова. По случайности, всю компанию заносит в Африку, где Алекс встречает свою семью, с которой он был разлучён в детстве. Неожиданно для себя Алекс понимает, что после жизни в зоопарке у него гораздо меньше общего с родственниками, чем ему хотелось бы…",
 "f-wd151904": "Первая же миссия в качестве агента 007 становится его величайшим испытанием: ему выпадает сразиться с международной террористической организацией, опутавшей своей сетью всю планету. Используя богатый шпионский арсенал - от верного пистолета до навороченного спортивного авто - Джеймс Бонд вступает в поединок с ключевой фигурой сил зла, финансовым гением преступного мира Ле Шиффром.",
 "f-wd190910": "Саблезубый тигр Диего, мамонт Мэнни, грызун Скрат и ленивец Сид дожили до глобального потепления. Но появилась новая беда: стремительный паводок идет прямиком к их родной долине. Теперь ответственным животным придётся спасать соседей от потопа, что довольно проблематично — строить ковчег совершенно не из чего, кроме как из талого снега. Но не беспокойтесь — эвакуация разнообразной живности в сухое место пройдёт не менее суетливо, смешно и успешно, чем и прошлая операция по возвращению человеческого детёныша в лоно семьи.",
 "f-wd233464": "Главный герой фильма, работающий комиком, с юмором и иронией рассказывает о своей жизни, о людях, которые его окружают. Он скептически анализирует свои неудачи в личной жизни, в которой было несколько любимых женщин…",
 "f-wd192934": "Весь мир замер в ожидании свершения древнейшей церемонии — выбора главы католической церкви Папы Римского, но в судьбоносное решение вмешивается некая могущественна сила — заклятый враг католической церкви — таинственный орден Иллюминатов! Кандидаты на священный пост подвергаются свирепой ритуальной расправой один за другим.",
 "f-wd50861": "На этот раз Джону Макклейну предстоит спасти родную страну от группы компьютерных террористов, собирающихся в буквальном смысле «отключить» Соединённые Штаты Америки. А если учесть, что Джон - человек прежней формации, то в борьбе, в которую вовлечены новейшие технологии, ему, кроме старой доброй «Беретты», понадобится молодой, но очень талантливый помощник, хакер Мэтт Фэррелл.",
 "f-wd631103": "После домашнего обучения за границей Кэйди попадает в американскую старшую школу и быстро узнаёт, что к чему, став одной из популярных девчонок.",
 "f-wd245366": "После долгой зимней спячки черепаха Верн просыпается и обнаруживает, что прямо у леса вырос огромный жилой квартал, а привычные запасы еды исчезли. В это же время появляется хитрый енот ЭрДжей, который убеждает зверей отправиться к людям за лёгкой добычей — горой вкусной, но незнакомой пищи. Для обитателей леса это шанс быстро запастись провизией, хотя Верн чувствует, что соседство с людьми опасно. Пока звери осваивают мусорные баки, печенье и газировку, между осторожностью и соблазном разгорается конфликт. Постепенно они понимают, что настоящая ценность — не в украденной еде, а в дружбе, доме и умении держаться вместе перед лицом опасности.",
 "f-wd8885676": "В будущем человечество, столетиями безоглядно эксплуатировавшее природу, пало жертвой своей гордыни. Землю постигла ужасная экологическая катастрофа, процветающие когда-то промышленные цивилизации обратились в прах, а поверхность планеты покрыло гигантское море Леса, испускающее в атмосферу ядовитые споры растений.  Оставшимся в живых людям приходится жить в тени Леса и его чудовищных насекомообразных обитателей, пытаясь не допустить распространения вредоносной растительности. Мирная Долина Ветров - одно из царств, образовавшихся на руинах прежних государств. Но безмятежное существование Долины Ветров нарушается, когда маленькая страна становится пешкой в играх крупных воинственных соседей, сражающихся за остатки драгоценных природных ресурсов планеты.",
 "f-wd318428": "Ежегодный конкурс гигантских овощей приближается. Два предприимчивых друга решили заработать денег на борьбе с грызунами. Но внезапно огромное таинственное животное начало терроризировать округу, уничтожая овощи, которые могли претендовать на главный приз конкурса. В отчаянье, пытаясь спасти мероприятие, его организатор леди Тоттингтон обещает царские почести тому, кто поймает зверя и спасёт праздник.",
 "f-wd117315": "Середина 19-го века. Немая Ада вместе с маленькой дочерью и любимым пианино покидает родную Шотландию и переезжает на другой конец света, в Новую Зеландию, где ее ждет будущий муж Стюарт. Он отказывается доставить в дом пианино, которое остается брошенным на берегу. Ада, не говорящая с шести лет, все же показывает мужу всю глубину своего гнева. Для этой сильной женщины молчание далеко не знак согласия. Сосед Стюарта Бэйнс, похожий на дикаря, привозит пианино, заменяющее Аде голос, к себе домой. Она может получить его назад, но только если будет приходить к Бэйнсу домой и давать ему уроки музыки — по числу клавиш. Эти уроки заведут их в пучину роковых страстей…",
 "f-wd936194": "Жизнь на ферме проста и привольна. Хозяева и питомцы живут душа в душу, поют песни и веселяться. Но внезапно этой идиллии приходит конец. На смену обанкротившимся владельцам фермы приходит безжалостный делец, желающий продать землю и избавиться от животных.Естественно, это не устраивает привыкших к сладкой жизни четвероногих и пернатых обитателей. Начинается потрясающе смешная «партизанская война». Руководителями бунта выступают конь Бак и три коровы-непоседы, решившие пойти на все, чтобы спасти ферму от разорения…",
 "f-wd62730": "Осень 1941 года. Немецкая подводная лодка отправляется в Атлантический океан, место противостояния германского и английского флотов. Жизнь по строгому распорядку, учебные тревоги, воспоминания о семьях и любимых девушках, солёные мужские шуточки... Скоро всё это закончится. Потому что впереди — ад и никакой надежды на спасение...",
 "f-wd218999": "События, исторически достоверно воспроизведенные на экране, происходят в Англии XVI века, во времена правления короля Генриха VIII. В основе сюжета — конфликт между королем и лордом-канцлером Томасом Мором, великим гуманистом, государственным деятелем, выдающимися юристом и философом.",
 "f-wd152493": "В роскошной усадьбе на западном берегу Лонг-Айленда обитало семейство миллионеров Лэрраби. Отец, мать и два сына. Старший - Лайнус - умный, младший - Дэвид - красивый. В Дэвида была безответно влюблена юная дочь шофера семьи Сабрина. Чтобы «излечить» дочь от любовной лихорадки, отец отправляет её в Париж в школу поваров. Через несколько лет домой возвращается изысканная утонченная красавица. Её чувства не прошли, но теперь уже и Дэвид покорен ею. Семейные планы расширения бизнеса за счет удачной женитьбы непутёвого сына под угрозой… Старший брат готов мужественно принять удар на себя и поухаживать за навязчивой девчонкой…",
 "f-wd22970530": "Когда-то викинги жили в гармонии с драконами. В те времена они делили радость, горе и последние штаны. Казалось, что так будет всегда, но появление загадочной Дневной Фурии изменило жизнь острова. И теперь Иккинг и Беззубик столкнутся с безжалостным охотником на драконов, жаждущим уничтожить все, что им дорого.",
 "f-wd244398": "Маленькая английская деревенька отделена древней стеной от сверхъестественной параллельной вселенной, где царят магия и волшебство. Молодой Тристан Торн опрометчиво обещает самой красивой девушке деревни, что принесёт ей слетевшую с неба звезду, упавшую по ту сторону стены. На своём пути по следам древних легенд Тристан встретит всесильного короля и его заговорщика-сына, могущественную ведьму, капитана пиратского корабля и хитроумного торговца, а также найдёт свою истинную любовь, о которой он мог только мечтать.",
 "f-wd337090": "Фильм о легендарной исторической личности. В нем большое внимание уделено историческим фактам и политическим событиям, имевшим место в период правления короля Артура. Но картина обещает совместить в себе как реальные исторические события, имевшие место в провинции Британия сразу после распада Великой Римской Империи, так и мифы о подвигах рыцарей короля Артура…",
 "f-wd501105": "Ричард знакомится в Лондонском мюзикхолле с Аннабеллой, которая просит укрыть ее от идущих по ее следу убийц. Ричард не воспринимает это всерьез, но разрешает ей переночевать у него. Той же ночью девушка вваливается в его спальню с ножом в спине… Бегущего в панике Ричарда принимают за убийцу-маньяка и полиция всей Англии начинает охоту. Чтобы доказать свою невиновность, ему придется пройти все круги Ада…",
 "f-wd752301": "Родди живёт в роскошной квартире, где он привык к комфортной и беззаботной жизни. Но однажды в доме появляется канализационная крыса Сид, которая случайно сталкивает Родди в раковину, и тот оказывается в совершенно незнакомом подземном мире. Пытаясь вернуться домой, Родди знакомится с отважной Ритой — капитаном небольшого катера, которая помогает ему выбраться из опасных передряг. Вместе они оказываются втянуты в планы злобного Толстопуза, мечтающего избавиться от жителей канализации. Теперь Родди и Рите предстоит остановить его замысел, спасая подземный город и самих себя.",
 "f-wd224004": "Агенты американской и французской разведок пытаются разоблачить советских шпионов на Кубе. По полученной информации, советский разведчик внедрился в структуру НАТО. Им предстоит узнать, кто скрывается под кличкой «Топаз». Проведенное расследование приводит агентов в высшие эшелоны Французского правительства…",
 "f-wd237116": "Марти — мясник, живущий со своей матерью в Бронксе. Добродушному и одинокому, ему нелегко быть частью окружающего его социума. Однажды он встречает непривлекательную школьную учительницу и понимает, что между ними есть эмоциональная связь. Он обещает ей позвонить, однако его семья и друзья пытаются отговорить Марти…",
 "f-wd4444": "Уэсли Гибсон — зануда и нытик, целыми днями торчащий в офисе. Босс его унижает, подружка ему изменяет. Его жизнь катится в никуда! Обнаружив, что отец, бросивший его в раннем детстве, зверски убит, Уэс оказывается втянут в тайное общество киллеров под названием «Братство». За его обучение берётся опытная наставница Фокс, и этот когда-то прикованный к офисному креслу хлюпик развивает молниеносную реакцию и сверхчеловеческую скорость. Однако уже на первом задании Уэсли понимает: есть вещи посложнее, чем вершить судьбы других людей. Это — набраться храбрости и стать хозяином собственной жизни.",
 "f-wd118976": "На западные рубежи Руси наступают войска Тевтонского Ордена. Они захватывают Псков, мучают и убивают местных жителей. Рыцари заранее делят ещё не завоеванные русские земли, присваивая себе титулы князей и надеясь на поддержку Папы Римского. Новгородский люд на вече решает собирать дружину и звать на командование ей опытного полководца князя Александра, прозванного Невским. Двое богатырей — Гаврила Алексич и Васька Буслаев (реальные личности) — сватаются к одной девице, и она решает, что выберет того, кто лучше покажет себя в битве.",
 "f-wd84147": "Красивая, молодая женщина из дворянской семьи, чья жизнь была одинокой и пустой, несмотря на блестящую с виду жизнь с мужем и сыном, в атмосфере русского царского двора… решительный молодой офицер c высоким дворянским титулом и страстным сердцем… дело, которое началось как тайная влюбленность, о которой, однако, скоро судачил весь город…",
 "f-wd380803": "Инженер Лось создает космический корабль для полета на Марс. В полете его сопровождает красноармеец Гусев, мечтающий немедленно организовать на Марсе революцию, и детектив Кравцов, подозревающий Лося в убийстве жены.",
 "f-wd153593": "По повести Дмитрия Фурманова. Урал в 1919 г. Гражданская война. Отряды храброго крестьянина Чапаева воюют с белой армией Колчака. Василий Иванович Чапаев (Борис Бабочкин), командир 25-ой дивизии Красной армии, готовится к решающему сражению с отборными частями каппелевцев, возглавляемых опытным кадровым офицером, полковником Бороздиным (Илларион Певцов). Партия присылает ему на помощь Дмитрия Фурманова (Борис Блинов) — молодого, но образованного и умного комиссара, чьи мемуары впоследствии легли в основу романа и фильма, обессмертившего имя Чапаева в памяти советских граждан.",
 "f-wd541354": "Фауст — учёный, озабоченный вопросами познания. Век просвещения и гуманизма подходит к концу. Распотрошив человеческое тело, Фауст не находит в нём души. Его униженный друг Вагнер пытается вырастить в пробирке идеального человека — гомункулуса. Главный герой уже не хочет покорить весь мир: его манят деньги и плотские удовольствия. Ради этого он отправляется к Мефистофелю, который преспокойно живёт в городе под видом ростовщика Маврикия. Дьявол с удовольствием берётся помочь Фаусту, даже не требуя расписки. Фауст встречает прекрасную девушку Маргариту, чьего брата он убил в пьяной драке после того, как Мефистофель из ниоткуда добыл вино солдатам. Теперь Мефистофель-Маврикий предлагает доктору Фаусту роковой договор. Тот соглашается, не в силах противиться соблазну овладеть невинной Маргаритой, даже если ради этого нужно убить её мать.",
 "f-wd1272202": "Скромный страховой агент и актёр театра самодеятельности Юрий Деточкин оказывается непримиримым борцом за справедливость. Он угоняет машины взяточников, продаёт их, а вырученные деньги перечисляет детским домам. Правда, для правосудия, представляемого актёром того же театра, а в миру — следователем Подберёзовиковым, этот Робин Гуд представляется хитроумным, изобретательным и неуловимым преступником.",
 "f-wd1330689": "Выйдя из тюрьмы, Егор Прокудин, по кличке Горе, решает податься в деревню, где живет синеглазая незнакомка Люба, с которой он переписывался - ведь надо немного переждать и осмотреться. Но жизнь в деревне рушит все планы Егора, и он решает навсегда порвать с прошлым. Теперь у него есть друзья, работа. Он любит Любу. Однако дружки Егора упорно не отпускают его.",
 "f-wd383581": "Фильм о семье советского репатрианта Алексея Головина, вернувшегося после войны в СССР с женой француженкой. Эта история произошла 50 лет назад. Это было суровое время. И какой же страстной была тогда любовь разлученных, и как безоглядно жертвовали они собой ради другого человека…",
 "f-wd26198150": "Ольга, русская аристократка, эмигрантка и участница французского Сопротивления, во время неожиданной проверки арестована нацистами за то, что прячет еврейских детей. В тюрьме ею увлекается Жюль, француз-коллаборационист, который ведет ее дело и в обмен на интимные отношения, кажется, готов смягчить ее участь. Ольга готова на все, чтобы избежать пыток, но ее надежда на свободу быстро рассеивается, так как события принимают неожиданный поворот.  Ольгу отправляют в концентрационный лагерь, где ее жизнь становится адом. Там неожиданно для себя она встречает Хельмута, высокопоставленного немецкого офицера СС, который когда-то был безнадежно влюблён в нее и до сих пор ее любит. Между ними завязываются странные, болезненные отношения. Хельмут решает бежать с Ольгой, хотя она уже перестала надеяться на спасение. Однако постепенно представление Ольги о Рае неотвратимо меняется.",
 "f-wd1428430": "Космические ракеты взрываются при взлете, а количество сообщений о наблюдениях НЛО постоянно увеличивается. Вскоре пришельцы из погибшей внегалактической цивилизации попытаются вторгнуться на Землю на непроницаемых летающих тарелках, используя против людей лучевое оружие массового поражения.",
 "f-wd1409466": "ХVI век. Лифляндия. В одном из аристократических домов умирает старый рыцарь Рисбитер. Он завещал сыну шкатулку с семейной реликвией. Духовные пастыри ближайшего монастыря хотят завладеть шкатулкой, чтобы приумножить славу обители.  Молодой наследник согласен уступить церкви реликвию, но с одним условием: ему должны отдать в жены прекрасную Агнес, племянницу аббатисы женского монастыря. А сердце юной красавицы принадлежит свободолюбивому рыцарю в Габриэлю, другу всех обманутых и беззащитных…",
 "f-wd2369914": "Крупная корпорация выпускает человекоподобных роботов, несмотря на общественное мнение, прессу и профсоюзы, которые выступают против. Принимается решение отправить космический корабль к Сатурну для запуска искусственных спутников, где экипаж будет состоять из роботов. Для осуществления полета выбирается пилот Пиркс, известный своей честностью и неподкупностью. Недоброжелатели из корпорации опасаются, что мнение Пиркса может сорвать прибыльное производство, и принимают свои меры.",
 "f-wd26797463": "7 декабря 1988 года в Армении произошло землетрясение, охватившее почти половину территории республики. Были разрушены города Спитак, Ленинакан, Кировакан, Степанаван и ещё более 300 населённых пунктов. 25 тысяч человек погибли, 19 тысяч стали инвалидами, больше полумиллиона остались без крыши над головой.  На фоне природной катастрофы разворачивается история двух героев — 45-летнего Константина Бережного и 20-летнего Роберта Мелконяна. Судьба сталкивает их не впервые — много лет назад в автокатастрофе по вине Бережного погибли родители Роберта. Константин провел несколько лет в тюрьме, а маленького Роберта приютили родственники. По странному стечению обстоятельств Бережной возвращается к своей семье в день страшного землетрясения: его ждут жена, дочь, сын… и Роберт, который так и не простил ему гибели своих родителей. По иронии судьбы, герои оказываются в одном спасательном отряде, но узнают друг друга не сразу.",
 "f-wd1975020": "Советские и американские войска встречаются на берегах Эльбы в последние дни Великой отечественной войны. Советское командование пытается наладить мирную жизнь в разоренной Германии. Американцы же с помощью бывшего нациста пытаются получить секретные военные разработки...",
 "f-wd3198577": "Биографическя лента о жизни и творчестве великого русского композитора Михаила Ивановича Глинки, о его учёбе в Италии, о создании опер “Иван Сусанин” и “Руслан и Людмила”. Узнав, что последняя посвящена А.С. Пушкину, Николай I усматривает в этом крамолу. Горькие переживания композитора скрашивают его единомышленники - передовые люди России...",
 "f-wd2096663": "Историко-революционная лента с обилием великолепно поставленных батальных сцен рассказывает о полководце Николае Щорсе, легендарном герое гражданской войны.  Действие происходит на Украине в 1919 году, когда войска красных шли к Киеву. Предстояли бои с войсками Петлюры и Драгомирова…",
 "f-wd3916267": "В этом доме детей с юных лет приучали всегда отчетливо говорить «мой»: мой пароход, мой дом, моя фабрика. Здесь считали деньги, нажитые чужим трудом, и за ночь спускали в карты целое состояние; здесь развратничали напропалую и втихомолку шпионили друг за другом; молились и совершали именем господа темные дела. Все было у Вассы - деньги, сила, власть, ум и хватка. Но не было у нее одного - будущего...",
 "f-wd4296432": "По романам Мариэтты Шагинян «Месс‑Менд, или Янки в Петрограде» и «Лори Лэн, металлист».\r Миллионер Гордон Сторн, о насильственной смерти которого сообщила вся американская пресса, на самом деле находится в руках главы профашистской организации Чиче, который вынуждает пленника подписать «завещание», в результате которого большая часть его денег поступит в распоряжение фашистов. Втайне от бандитов Сторн успевает написать другое письмо, адресованное генеральному прокурору. Это письмо попадает в руки трёх друзей — репортера Барнета, фотографа Фогеля и клерка Гопкинса. Именно они и путают все карты Чиче…\r Действие первой серии («Письмо мертвеца») происходит в начале 1920‑х годов в СШ А. Во второй серии («Преступление двойника») действие переносится в ССС Р. Действие третьей серии («Смерть по радио») происходит в Ленинграде в середине 1920‑х годов.  Один из самых кассовых фильмов 1920‑х годов. Озвучен в 1957 году.",
 "f-wd1970834": "Талантливый пианист Андрей Балашов, воспитанник Московской Консерватории, после ранения на фронте лишился возможности заниматься любимым искусством. Решив уйти от друзей, от любимой девушки, певицы Наташи Малининой, Андрей уезжает в Сибирь, где работает чертёжником на строительстве бумажного комбината, а по вечерам выступает с песнями в чайной. Неожиданная встреча с друзьями и Наташей убеждает его в том, что он понапрасну растрачивает свой талант. Он уезжает в Заполярье, где, вдохновлённый героическим трудом строителей, пишет симфоническую ораторию «Сказание о земле Сибирской», которая получает всеобщее признание.",
 "f-wd3909579": "Билетер кинотеатра Гога Палкин влюблен в студийку Дусю Галкину, мечтавшую о славе кинозвезды. Дуся обещает ему взаимность в том случае, если Гога станет знаменитостью. Случайно попав на киностудию, после ряда приключений, Палкин оказывается под куполом ателье, а все участники съемки едут встречать американских кинозвезд. Прибыв на студию, Мэри Пикфорд находит Гогу Палкина весьма забавным, дарит ему свой поцелуй - и Гога становится знаменитым.",
 "f-wd3228140": "Из жизни русской деревни перед революцией и первых послеоктябрьских лет. О тяжелой судьбе солдатской жены Анны, кончающей жизнь самоубийством. О живой и энергичной сестре мужа Анны, Василисе, открыто бросающей вызов старому укладу жизни.",
 "f-wd1035180": "На вечеринке популярная фотомодель Джениффер Три неожиданно теряет сознание после выпитого коктейля. Она оказывается в подвале частного жилого дома, понимает, что похищена.  Вскоре за стеклянной стеной, разделяющей комнаты, она обнаруживает также плененного молодого человека — водителя Гарри. Молодые люди общаются через стекло, надеясь на побег. С целью избежать судьбы предыдущих жертв маньяка, они пробуют бежать, но каждый раз попадают в искусно расставленную ловушку.",
 "f-wd1284566": "Учитель истории Мельников много размышляет, строго и требовательно спрашивает. Ему знакомы и сомнения, и моменты усталости, и неудовлетворенность. И Мельников не всегда прав. Но он борется, ищет, любит, преодолевает трудности и сомнения. Один из лучших советских фильмов о школе, о сложных взаимоотношениях учеников и педагогов, о том, как важно встретить в жизни настоящего Учителя...",
 "f-wd2509532": "Осень 1866 года. Великий Достоевский, находящийся под надзором полиции, в ужасном положении: менее чем за месяц он должен завершить роман «Игрок», в противном же случае он на многие годы попадет в кабалу к издателю. В эти дни судьба сводит Достоевского с юной Анной Сниткиной, которая становится добрым гением писателя, его помощницей, спасительницей, женой.",
 "f-wd2972912": "Они познакомились двадцать лет назад и полюбили друг друга, но война разлучила их. Теперь Ильин и Тамара Васильевна встретились вновь, и любовь вспыхнула с новой силой…",
 "f-wd4287588": "Литва первой половины XIX столетия. Среди лесов высится феодальный замок графа Шемета. Однажды во время охоты на графиню нападает медведь. Пережитое потрясение лишает ее рассудка.  Рожденный графиней сын приобретает патологические черты характера, свидетельствующие о вырождении рода. Молодой граф, испытывая болезненную жажду крови, нападает на крестьянок. Местные жители ненавидят графа, отождествляя его с легендарным оборотнем Локисом...",
 "f-wd1995073": "Середина XIX века. В оккупированной австрийскими войсками Италии действуют силы сопротивления. Внутри этих событий - история человека, превратившегося из чистого восторженного юноши в непримиримого борца за независимость, легендарного и неуловимого овода.",
 "f-wd3297214": "По одноименной драме М. Ю. Лермонтова. Арбенин Евгений Александрович, бывший карточный шулер, наивно полагал, что из игры можно выйти и прошлое можно забыть. Трудно сказать, что на самом деле стало причиной трагических событий, произошедших в его семье.  Были ли то интриги некоего Неизвестного, некогда разоренного им? Или же это была расплата за совершенные им грехи? Доподлинно известно одно: причастными к этой темной истории оказались многие из лиц ему известных.",
 "f-wd2912561": "1997 год. Пропавший три года назад Николас Баркли, мальчик из простой техасской семьи, невероятным образом найден в Испании. Семья счастлива: их не смущает даже то, что парень сменил цвет волос и глаз, говорит с акцентом и никого не узнаёт. На самом деле это Фредерик Бурден: самозванец-виртуоз и мастер обмана, менявший свою личность по меньшей мере 39 раз. Разоблачить мошенника Бурдена пытаются агент ФБР и частный детектив, но их ждёт встреча с куда более мрачными тайнами. Ведь у каждой лжи — две правды.",
 "f-wd239756": "78-летний профессор из Стокгольма вспоминает и пересматривает разочарования своей долгой жизни. Вместе с женой сына он едет на машине на вручение почетной докторской степени, посещая по пути места, где был молод, встречая разных людей и старых знакомых, вспоминая сны и былое.",
 "f-wd1256208": "Это фильм для тех, кто думает, что он уже не верит в Санта Клауса. Далеко в заснеженных горах Лапландии, в ущелье на глубине 486 метров обнаружили находку, надежно укрытую от всех. Теперь пришло время открыть ее миру.",
 "f-wd1546938": "После пребывания в буддийском монастыре, бывший беспощадный правитель огромной наркоимперии, а ныне добропорядочный гражданин, скрыв лицо под маской, борется со злом в самом страшном городе мира - Нью-Йорке. Но вот у него появляется соперник не менее могущественный, чем он сам - потомок Чингисхана, стремящийся подчинить себе весь мир...",
 "f-wd126009194": "Россия, начало 1990-х годов, последствия распада СССР. В новом мире, обещающем свободу и граничащем с хаосом, молодой художник, ставший телепродюсером, Вадим Баранов неожиданно становится спин-доктором перспективного сотрудника ФСБ (бывшего КГБ) Владимира Путина.",
 "f-wd352000": "Нео-нацист, приговорённый к общественным работам в церкви, сталкивается с крайне праведным священником.",
 "f-wd571164": "Действие фильма разворачивается на бескрайних просторах Антарктики. Научная экспедиция, в состав которой входят Джерри Шепард, его лучший друг Купер и геолог, отправляется на поиски метеорита. Однако неожиданное происшествие и тяжелые погодные условия вынуждают их оставить свои собачьи упряжки и вернуться назад. И теперь восемь собак должны в течение шести месяцев бороться за выживание в ледяной пустыне и ждать, пока их спасут…",
 "f-wd130907516": "Улисс приезжает в небольшой городок Нормал, чтобы временно занять должность шерифа. Город кажется безопасным, почти сонным и дружелюбным. Но после ограбления банка Улисс обнаруживает преступный заговор, в который вовлечён весь город. Теперь ему предстоит решить, готов ли он пойти до конца и разрушить кажущуюся идиллию.",
 "f-wd80660": "19-летний Томек — вуайерист. В свободное от работы на почте время он подглядывает за красоткой напротив Магдой — сперва через бинокль, который завещал ему уехавший друг (тоже вуайерист), а теперь более основательно — через подзорную трубу. Поставленный еще приятелем диагноз: «КПЧД» (красивая попа, часто дает) — в результате наблюдений остается без изменений.\r Однако чувства Томека к Магде носят хотя и патологически влюбленный, но при этом платонический характер. Узнав о том, что она находится под наблюдением юноши, Магда сама начинает испытывать к Томеку чувственный интерес, что неожиданно для всех приводит к драматическим последствиям…",
 "f-wd1061541": "Приговоренный к шести годам тюрьмы Малик Эль Джебена кажется на фоне других заключенных самым «зеленым» и самым уязвимым. Ему 19 лет. Он не умеет ни писать, ни читать. За стенами тюрьмы у него нет близких.\r Всё меняется, когда Лучано, лидер авторитетной банды корсиканцев, решает поручить Малику ряд опасных и рискованных заданий, выполнение которых под прессингом корсиканцев могло бы сломить кого угодно, но не его. Каждое задание закаляет Малика. Он быстро учится жизни в новом для себя мире. Завоевывает доверие корсиканцев и мусульман. И вскоре начинает вынашивать собственные дерзкие планы.",
 "f-wd124829697": "В этом фильме номинанта на премию «Оскар» Ноа Баумбаха кинозвезда Джей Келли сталкивается с прошлым и настоящим во время путешествия по Европе с преданным менеджером.",
 "f-wd116257424": "В поисках своей второй половинки Шерил Брэдшоу отправляется на популярное телешоу «Игра в свидание». Ее избранником становятся остроумный и харизматичный холостяк Родни Алькала. Но за его очаровательной внешностью скрывается смертельно опасный секрет: Родни — хладнокровный серийный убийца и психопат, готовый на всё.",
 "f-wd47899984": "Перед высадкой в Нормандии группа американских десантников должна выполнить важную миссию, от которой зависит исход сражения. Но, приближаясь к цели, солдаты осознают, что эксперименты нацистов привели к жутким последствиям.",
 "f-wd20666646": "Зло всегда возвращается. Его нельзя укротить или подчинить — лишь на время остановить. Можно выстрелить в него, сжечь дотла, но оно всё равно восстанет из тьмы. Майкл Майерс ещё не закончил своё дело в Хэддонфилде. И вскоре он снова вернётся домой… чтобы убивать.",
 "f-wd21822504": "Лос-Анджелес начала 1980-х. Компания молодых людей решает провернуть аферу, благоприятный исход которой сулит огромные деньги. Схема обогащения оказывается жизнеспособной и вместе с тем — смертельной.",
 "f-wd32362264": "В декабре 2017 будет жарко! Дружба Жени и Бори едва не сгорит в огне семейного скандала; глубоко беременная Снегурочка отправится в Одиссею по нижегородским семьям; отчаянная Галя из Новосибирска пойдет на все, чтобы провести ночь с любимым врачом; экстремальный поход в лес за елкой станет проверкой на прочность для юного хипстера из Тюмени и его потенциального отчима. Новые и хорошо знакомые герои «Ёлок» влюбляются, ссорятся и мирятся, совершают геройские поступки и попадают впросак, лишь бы найти на Новый год настоящую родственную душу, как один смелый мальчик из Хабаровска, сбежавший в поисках новой мамы в Москву. И помочь им может только чудо… или вся страна!",
 "f-wd20762698": "Неважно кто ты: грабитель банков или домохозяйка - все рвутся к славе. Овца, горилла, бык или даже свинья - каждое животное мечтает стать звездой. Всё как у людей.",
 "f-wd22075020": "Все думали, что Ксандер вместе со своей девушкой Еленой погиб при таинственных обстоятельствах. Но это оказалось всего лишь прикрытие. Прошло 8 лет после того как любитель экстрима Ксандер Кейдж пропал из вида АНБ после якобы его убийства на Бора-Бора. Но теперь он возвращается из самоизгнания в секретную службу и готов выполнять новые сверхсекретные задания. Его новая миссия будет направлена на поиск секретного оружия невероятной мощности, которое несёт угрожающее название — «Ящик Пандоры». Так же Кейджу будет противостоять синдикат мировых преступников под руководством альфа-воина Сяна. У которого свои планы на этот экспонат. В добавок ко всему Ксандера не покидает мысль о кроте в организации и заговора на самом высоком уровне. От исхода их противоборства теперь вновь стоит судьба все обитателей Земли.",
 "f-wd15715216": "История об элитном убийце, созданном при помощи генной инженерии, который объединяется с женщиной, чтобы помочь ей найти отца и раскрыть тайну своего происхождения.",
 "f-wd20038326": "После окончания жестокой Мировой Войны в Японии наука сделала резкий скачок вверх и начала развиваться не по дням, а по часам, давая человечеству выбор продолжать жить и ослаблять страдания с помощью современной кибернетики. Все человечество связано с помощью системы умов и личностей, известных как «Призраки». Самой большой угрозой цивилизации являются кибер-террористы, которые способны украсть человеческие тела и память.  Когда вирус под названием FIre-Starter заражает систему и начинает распространяться, происходит убийство премьер-министра Японии, совершенное таинственным киборгом. Майора Мотоко Кусанаги и её элитную команду оперативников специального назначения призывают выследить источник заражения. Копаясь всё глубже и глубже в расследовании, они обнаруживают следы правительственной коррупции и подозрительного брокера, который может иметь к этому отношение.",
 "f-wd101002778": "Воскреснув из мёртвых, клоун-маньяк Арт отправляется в прачечную, где встречает похожую на него девочку. А тем временем старшеклассница Сиенна готовится к Хэллоуину и делает костюм по эскизу недавно умершего отца. Хотя ей не терпится в компании подруг отправиться на вечеринку, девушку начинает одолевать тревожное чувство. И не зря. Арт тоже подготовился к празднику, смастерил себе оружие и приступает к любимому занятию — извращённым убийствам.",
 "f-wd1954593": "Бывалому медвежатнику Аркину чудесным образом удалось выбраться из ловушек, расставленных по дому загадочным маньяком Коллекционером. Аркин был уверен, что он никогда в жизни больше не встретится с Коллекциoнером, но cудьба распоряжается иначе.",
 "f-wd1749311": "После того как жителей отдаленного городка в штате Невада стал безжалостно истреблять невидимый враг, владелец копей Хайрем Гаммер нанимает лучшего стрелка на Диком Западе по кличке Келли Черная Рука, чтобы тот расправился со зловещими существами, оставляющими уважаемого бизнесмена без прибыли! Надо заметить, что мистер Гаммер является прапрадедом Берта Гаммера — отважного охотника и эксперта по истреблению прожорливых подземных хищников. Так что, как Вы, наверное, уже догадались, кровопролитных схваток с огромными плотоядными червями теперь не избежать!",
 "f-wd83542": "Элис оказывается в секретном подземном комплексе «Амбреллы», где корпорация проводит эксперименты над вирусом и создаёт копии людей и целых городов. Пробираясь через искусственно воссозданные районы, Элис сталкивается с противниками из своего прошлого и пытается понять, кому можно доверять. Вместе с неожиданными союзниками она сражается за свободу и стремится остановить планы «Амбреллы», пока корпорация не использовала вирус для окончательного уничтожения человечества.",
 "f-wd113300899": "Пожертвовав собой, чтобы спасти возлюбленную, Эрик Дрэйвен застревает между мирами живых и мёртвых. Он возвращается с того света, чтобы свести счёты с убийцами. Отныне он — Ворон, жаждущий справедливости, и его месть будет жестока как никогда.",
 "f-wd2080262": "Действие происходит в недалеком будущем. Главный герой, Михаил Галкин, замечает, как вокруг накапливаются перемены… Происходят события, казалось бы, не связанные между собой… Он обнаруживает глобальный заговор и понимает, что за этим заговором стоят скрытые силы, контролирующие наш мир. И эти силы не принадлежат человеческой цивилизации. Герой начинает против них войну. Войну, которую нельзя проиграть.",
 "f-wd73279": "Мия отправляется вместе с братом Дэвидом и его друзьями в уединённый домик в лесу, чтобы избавиться от наркотической зависимости и начать новую жизнь. В подвале они находят загадочную книгу, покрытую человеческой кожей, и по незнанию пробуждают древнее демоническое зло. Вскоре Мия начинает вести себя всё более странно, а остальные понимают, что в доме происходит нечто сверхъестественное. Отрезанные от внешнего мира, они пытаются выжить и найти способ остановить демона, пока тот не завладел Мией окончательно.",
 "f-wd139326": "Рэнди «Баран» Робинсон был звездой 80-х, но стал бледной копией самого себя. Получив инфаркт во время одного из матчей, борец услышал от врачей неприятную весть: если он продолжит выступления, то может умереть. Пытаясь начать жизнь заново, Рэнди устроился работать в магазин и налаживал отношения с дочерью. Но уж больно заманчивой была перспектива матча-реванша со старым соперником по кличке Аятолла…",
 "f-wd1131556": "Гигантский бриллиант «Розовая пантера», подаренный индийским шейхом дочери Дале, станет наживкой, на которую должен клюнуть грабитель. Расставляя хитроумные сети, полицейский и не подозревает, что сам в них попадет, ведь любовник его жены — как раз тот самый фантом, которого он безуспешно пытается поймать.",
 "f-wd18740903": "Самому миролюбивому в мире быку, с детства предпочитавшему сидеть под деревом и нюхать цветы, а не бегать вокруг, сталкиваясь лбами с другими соплеменниками, выпал нелепый жребий судьбы — его как «самый большой, самый быстрый, самый дикий экземпляр» по ошибке выбрали для участия в бое быков в Мадриде.",
 "f-wd43370948": "Внедриться в Ку-Клукс-Клан – задача не из легких, особенно если ты чернокожий. Но целеустремленного полицейского из Колорадо такие мелочи не смущают. Вместе с напарником-евреем он вступает в неравный бой с опаснейшими противниками.",
 "f-wd388476": "Артур Бишоп - «Механик», высокопрофессиональный безукоризненный киллер, который всегда работает по правилам - «чисто» и без следов. Такая работа требует полного самообладания и беспристрастности, и в своём деле ему нет равных. Бишоп всегда работал один, но ему пришлось стать наставником молодого и отчаянного Стива. Методичный профессионал и импульсивный ученик теперь на пару «устраняют проблемы», но рано или поздно они сойдутся в смертельной схватке...",
 "f-wd43370937": "Пять лет назад мир погрузился в хаос: увидев нечто, люди кончают жизнь самоубийством. Женщина с двумя пятилетними детьми, услышав по радио о безопасном месте, отправляется на поиски выжившей общины и прихватывает с собой попугаев в коробке. Чтобы сохранить жизнь в этом новом мире, самое главное — не смотреть по сторонам и слушать, как птицы реагируют на приближающуюся опасность.",
 "f-wd571197": "Герои фильма - Танго и Кэш. Эти соперничающие друг с другом копы обладают одной общей чертой: каждый думает, что он самый лучший, и каждый имеет бесспорные доказательства этого.",
 "f-wd18151446": "Отправив семью за город, архитектор Эван остаётся на выходных дома один доделывать срочный проект. К нему стучатся две милые девушки лет двадцати, насквозь промокшие и заблудившиеся. Эван не мог предположить, что протянув руку помощи, он получит в ответ череду изощрённых издевательств, изысканных пыток и медленного садистского уничтожения его семьи.",
 "f-wd60853529": "Молодая семья переехала в новую квартиру на окраине города. Нанятая ими для новорожденной дочери няня быстро вошла в доверие. Однако старший сын Егор рассказывает о пугающем поведении женщины, но родители ему не верят. Камеры наблюдения, установленные отцом для успокоения, лишь подтверждают — всё в порядке. И вот однажды, вернувшись домой, Егор не обнаруживает ни няни, ни маленькой сестры, а родители пребывают в странном трансе и даже не помнят, что у них была дочь. Тогда мальчик вместе с друзьями отправляется на поиски, в ходе которых выяснится, что няня — древний славянский демон.",
 "f-wd4365446": "Мучимый никчемностью и скукой жизни, чиновник Лаевский жаждет любой ценой разорвать порочный круг своего существования. Его нравственный антипод, натуралист Фон Корен, уверен, что люди, подобные Лаевскому, достойны уничтожения. Но, вопреки желаниям и воле героев, провидение по-своему распоряжается их судьбами…",
 "f-wd1976681": "Основанный на романе Виктора Пелевина фильм «Generation П» во многом строится на галлюцинациях - включая речь Че Гевары о том, почему и как телевидение разрушает человека. Однако через изменённую реальность проступает кропотливо восстановленная атмосфера Москвы в 90-е годы, на фоне которой и разворачивается действие картины. Вавилен Татарский, нашедший себя в новой жизни в роли сотрудника рекламного агентства, занимается продвижением западных брендов, адаптируя их под «русскую ментальность». Умный и местами чудовищно смешной, насыщенный спецэффектами и откровениями фильм делает простой и понятной сложную историю о том, как бывшие пионеры стали рекламщиками на службе у богини Иштар, а «поколение Пепси» выбрало Coca-Cola.",
 "f-wd23925050": "Мир устроен неправильно. Мир погряз во зле. Много лжи, вранья, лицемерия. Добродетель поругана. Вера утрачена. Главный герой, мальчик Вениамин, считает, что знает все о моральных нормах. Как их надо соблюдать, от кого их надо защищать, что такое хорошо и что такое плохо. Его поведение для окружающих становится серьезным испытанием. Где граница между моралью и нетерпимостью, свободой и вседозволенностью, проповедью и терроризмом, религией и манипуляцией?",
 "f-wd48941068": "В основе фильма реальная история уникального подвига экипажа танка «КВ-1». Приняв неравный бой, экипаж Семёна Коновалова уничтожил 16 танков, 2 бронемашины и 8 автомашин с живой силой противника в районе хутора Нижнемитякин Тарасовского района Ростовской области. Это история не плакатных героев, а разбитных, весёлых, очень разных парней, которые просто хотели жить, но в решающую минуту сумели принять единственно верное решение и совершить подвиг достойный легенды.",
 "f-wd107426602": "Северная Осетия, небольшой шахтерский городок Мизур зажат между отвесными скалами. Сюда перевез свою семью Заур. Сыновей и дочь он воспитывает строго, не зная границ между отцовской заботой и гиперопекой. Старший Аким уже сбежал в ближайший крупный город Ростов на заработки. Младший Дакко еще не вполне осознал, чего он хочет от жизни, а средняя Ада активно строит планы побега. Она уже взрослая девушка, но отец по-прежнему хочет видеть ее маленьким беззащитным ребенком. Разомкнуть крепкие отцовские объятия, чтобы наконец начать самостоятельную взрослую жизнь, оказывается сложнее, чем казалось.",
 "f-wd21405637": "Макс Андреев решил начать жизнь с чистого листа, для чего отправился на остров в Юго-Восточной Азии. Казалось, что теперь его идеальную жизнь ничто не нарушит, но однажды к нему приезжает старый друг из прошлой столичной жизни. Обстоятельства складываются так, что Макс возвращается на родину, где ему предстоит стать частью чего-то нового.  Казалось, что он уже давно осознал все свои ошибки, и больше никогда не повторит их. Но вскоре ему предстоит встретиться со своим прошлым, которое он так и не смог отпустить…",
 "f-wd47090972": "Прямо посреди дня из своего «мерса» похищен местный олигарх Калугин. Неизвестные в балаклавах потребовали за него большой выкуп. Отвезти деньги берётся глава личной охраны бизнесмена по кличке Туман. Его вооружённые до зубов «спецы» приезжают ночью на завод Калугина, где теперь босса держат в заложниках. Они пока не знают, что те другие, забаррикадировавшиеся в цехе — это местные рабочие во главе с бывшим спецназовцем по прозвищу Седой. Полгода без зарплаты и предстоящее банкротство завода толкнули их на отчаянный шаг. Чтобы вытащить своего хозяина, «спецы» не остановятся ни перед чем. Но в отличие от них «работягам» больше нечего терять…",
 "f-wd4146403": "Санкт-Петербург, 1908 год. Художнику Платону Андреевичу уже многие годы не дает покоя мысль о состязании со Всевышним. Преуспевающему оформителю витрин и театральных декораций хочется создать нечто совершенное и вечное, неподвластное течению времени - и таким образом встать рядом с самим Создателем. И вот Платон Андреевич получает заказ на женский манекен для оформления витрины ювелирного магазина. В качестве модели Платон находит совсем юную бедную девушку Анну Белецкую, умирающую от чахотки. И художнику удается запечатлеть ее предсмертную красоту в восковой кукле. Этот манекен становится вершиной его творчества и одновременно - его концом: создать что-либо более совершенное уже невозможно...",
 "f-wd129423731": "Спайк оказывается в банде отморозков Джимми, которые находят выживших и жестоко их убивают. А тем временем доктор Келсон, усмиряющий здоровенного альфу своим седативным коктейлем, замечает, что тот начинает проявлять признаки сознания.",
 "f-wd124735482": "Маня и Саня — обычные дети, живут в обычном приморском городе. Как и все дети, они любят играть в компьютерные игры. В один прекрасный день герои отправляются на берег моря, и неожиданно попадают в сказку.",
 "f-wd130428103": "Семён Семёнович Горбунков едет в круиз и останавливается в старом Дубае. Контрабандисты накладывают ему гипс, но не с бриллиантами, а с новыми смартфонами, фенами Dyson и прочими товарами, ввозимыми в страну путём «параллельного импорта». По заданию Шефа контрабандисты пытаются снять гипс с Горбункова, а сам он из скромного экономиста превращается в настоящего спецагента под кодовым именем «007-ён Семёнович».",
 "f-wd124806421": "После победы над Боузером и спасения Бруклина, Марио сталкивается со злобным альянсом Варио и Боузера-младшего. Теперь вместе со своими друзьями и Йоши он должен помешать их планам по завоеванию мирового господства.",
 "f-wd1625242": "Стивенс — образцовый английский дворецкий, который всю жизнь провел в старинном поместье. Он отдал свое сердце беззаветному служению, и нет ничего, что может заставить его изменить долгу. Неожиданно привычное течение дней нарушается, когда в поместье появляется новая экономка, мисс Кентон.  Стивенс пытается скрыть глубокие чувства к этой женщине, но ни вековая традиция, ни священные обязанности не могут остановить вспыхнувшую любовь. И лишь теперь, на закате дней, преданный дворецкий открыл для себя тот единственный идеал, который достоин истинного служения…",
 "f-wd4158437": "Коля Мухин и Алёша Кронов, семиклассники ленинградской школы, учатся в одном классе, но симпатии друг к другу не испытывают, так как Коля — отличник, а Алёша — двоечник и хулиган. Однажды, по вине Алёши, они прогуляли уроки и целый день провели в городе вместе, а события, происходившие с ними, не только помогли им получше узнать друг друга, но и в чём-то изменить своё отношение к окружающему миру.",
 "f-wd106298596": "Главный герой, чья судьба переплетается с темной стороной подпольного мира. Оказывается перед сложным выбором, из-за обещания данного другу в детстве. Это обещание становится его священным долгом и толчком к действию. Герой, смело бросает вызов преступным группировкам. Его поступки не только нарушают хрупкое равновесие в подпольном мире, но и вызывают цепную реакцию событий, которые влияют на всю преступную среду.",
 "f-wd113493289": "Вооружённая группа берёт в заложники пассажиров метрополитена, в числе которых — дочь влиятельного торговца оружием Кали. Лидер группы выдвигает требования об огромном выкупе, но поступившие от Кали средства преступники не забирают себе, а пересылают на счета тысяч фермеров, которые находятся на грани банкротства из-за действий министра сельского хозяйства. Перед тем как отпустить заложников, главарь просит дочь Кали передать отцу два слова — Викрам Ратхор.",
 "f-wd125861557": "Трагический несчастный случай вынуждает могущественного Сикандара защищать менее удачливых, противостоя коррупции и жадности — используя любые необходимые средства.",
 "f-wd111458251": "2019-ый. Теннисист Арт Дональдсон переживает не лучший период в карьере, поэтому, чтобы поднять его моральный дух и укрепить веру в себя, его жена и по совместительству тренер Таши предлагает принять участие в турнире серии ATP Challenger. В прошлом она сама была многообещающей спортсменкой, но не смогла восстановиться после травмы колена, и теперь все силы вкладывает в мужа. В финале Арт выходит на бывшего парня Таши и некогда своего лучшего друга Патрика Цвейга, для которого победа тоже становится делом принципа.",
 "f-wd132240259": "События этой киноленты разворачиваются в 1920-х годах, в период, когда Индия все еще ощущает гнетущее влияние британского владычества. В живописном районе Шрикакулам безмятежное поселение становится безвинной жертвой зверств, совершаемых колониальными войсками. Беспощадные расправы и волна насилия приводят к полному истреблению мирных семей, и лишь немногим удается избежать жестокой участи. Выжившие, израненные, но не потерявшие волю к жизни, вынуждены покинуть родные земли и искать новое пристанище на небольшом островке близ берегов Шри-Ланки, где начинается их новая, полная лишений жизнь.",
 "f-wd58411760": "Кабир выучился на хирурга и теперь пытается совладать со своим вспыльчивым характером. Именно вздорный нрав мешает Кабиру достигать успехов. Ему не раз приходилось участвовать в стычках в медицинском колледже, и несколько раз он даже оказывался на грани исключения. Жизнь главного героя меняется после того, как отец его девушки не даёт своё согласие на их свадьбу. Кабир не собирается переубеждать главу семьи своей невесты. Он находит утешение на дне бутылки и даже начинает употреблять наркотики. Что может спасти Кабира от окончательного падения в пропасть?",
 "f-wd734008": "Принц Ашока еще ребенком получил в руки меч, про который говорили, что это не меч, а настоящий дьявол, не различающий врагов и друзей. Вырос наследник престола на удивление мирным и покладистым, да настолько, что по просьбе матери отправился путешествовать под видом простолюдина.  В странствиях он влюбляется в скрывающуюся от врагов принцессу соседнего царства Калинга — Каурваки. Но когда Ашоку вновь призывают к трону, за который надо еще побороться с алчными до власти братьями, советник Каурваки убеждает принца в том, что прекрасной воительницы больше нет…  Ашока женится на другой, топит трон в крови братьев и решает завоевать Калингу. А виной всему — кровожадный меч. Осатаневший правитель Магадхской империи побеждает, но прозрение неизбежно, ведь Каурваки еще жива…",
 "f-wd1033304": "Каран Капур работает мультипликатором в одной из ведущих газет Индии. Проще говоря, он рисует комиксы. Самые популярные персонажи — Hum Tum, появляющиеся в его газетной колонке. Почему Hum Tum (ты и я)? Потому что так он видит разделенный мир. Нет стран, нет религий, только две проблемы — мальчики и девочки. Впервые он встретил Рею Пракаш в Амстердаме. Они спорили по любому поводу. Чтобы скрепить их дружбу, он позволил себе невинный поцелуй, но Рея закончила их встречу на плохой ноте. Спустя полгода дуэт встретился еще раз в парке в Нью-Йорке и Рея не забыла амстердамский поцелуй! В отместку она вынимает своего «кота из мешка» и Каран по ее милости лишается герл-френд. Пришло время новых отношений!..",
 "f-wd454674": "На бедную семью, которой и так не везет в этой жизни, посыпались одно несчастье за другим. Глава семейства вынужден был податься в бега, он скрывается от бандитов. Его жена от горя ослепла и сильно заболела. А их маленькие сыновья оставшись без присмотра родителей, потерялись. У каждого мальчика судьба сложилась по-своему. Мальчики вырастают, но они пока даже не подозревают друг о друге. Но, все-таки судьба благосклонна к ним и братья встретятся и обретут друг друга.",
 "f-wd1060540": "Сундер Шривастав на маленьком клочке земли открыл сельскую школу, выполняя последнюю волю своего отца. Но ни других учителей, ни классной комнаты в школе не было. Однажды к нему приехал старый друг детства из Бомбея, предложивший Сундеру поехать в Дубай и заработать там денег на новую школу. Сундер следует его совету, продает свой участок земли, дом, набирает нужную сумму денег, которую и вручает другу для приобретения билета и другие расходы. Но, приехав в город, Сундер обнаруживает, что старый друг обманул его и сам уехал на его деньги. К тому же у Сундера вытащили из кармана остатки денег и украли все вещи. Не имея никого знакомого в городе, Сундер не мог остановиться в Бомбее, но и в деревню вернуться не может...",
 "f-wd1656251": "После свадьбы Радха переезжает в дом мужа Гопала. В то же время она продолжает общаться с другом детства Сураджем. Именно ему она доверяет все свои тайны. Это вызывает раздражение и ревность молодого супруга. Он становится все более подозрительным. Гопал хочет, чтобы Радха оказывала внимание только ему, любила только его и была для него одной единственной…",
 "f-wd1192353": "У Джавета — честного копа из отдела по борьбе с наркотой четверо детей. Их мама обитает на небесах и светит сиротам в виде звезды. Напарник Джеки — Арун, детей терпеть не может и это чувство взаимное. Однажды в результате облавы на торговцев наркотиками таинственной смертью погибает Джавет. Теперь на плечи Аруна ложится забота о круглых сиротах.  Легко сказать, трудно сделать! Мало того, что дети его не «переваривают». Есть еще деревенская девушка Гита, непонятно как из влюбленной в него простушки превращается в высокомерную шикарную подружку главного злодея KKV. А после этого Аруна еще и «подставляют», обвинив в убийстве.",
 "f-wd1442306": "Меня зовут Изна. Я порнозвезда. Всю свою жизнь моё тело развлекало людей. А сегодня я умираю в полном одиночестве. Но перед смертью я обязана кое-что сделать. Я должна у одного человека попросить прощения за свои ошибки. Но сможет ли он меня простить? Или после смерти я вечно буду гореть в аду? Этому положила начало любовь.",
 "f-wd3025723": "Фильм повествует о пересечении судеб четырех человек, разделенных классовыми, религиозными и языковыми различиями.",
 "f-wd1378528": "Поэт-мусульманин Анвар Али, наряду с пятью другими мужчинами, все из разных религий и из разных частей страны объединяются с Марией, уроженкой Гоа оккупированного португальцами, чтобы поднять националистические настроения в стране и водрузить индийские флаги на португальские форты и здания. В ходе этой борьбы они сдружились друг с другом и забыли о своих религиозных и территориальных разногласиях.",
 "f-wd28914754": "Ньютон Кумар — самый честный госслужащий во всей Индии. Он трепетно относится к своей работе и всем сердцем мечтает изменить её в лучшую сторону. Когда в стране намечаются выборы, он первым вызывается отправиться в Дандакаранью, чтобы собрать голоса. Даже несмотря на то, что эти джунгли кишат наксалитами — безжалостными группировками, которые не любят незваных гостей.",
 "f-wd77892452": "Молодая женщина Амрита была уверена, что состоит в идеальном браке с любящим и заботливым мужчиной. Муж занимается карьерой, Амрита домашним хозяйством. Ее привычная жизнь рушится, когда супруг на вечеринке при всех дает ей пощечину. Удар по щеке буквально разделяет жизнь супругов на «до» и «после». Героиня, несмотря на советы родственников забыть об инциденте, не в силах смириться с грубостью и несправедливостью.",
 "f-wd841742": "У Баладжита всё отлично - молодая красавица жена, престижная работа в Бангкоке и дом на берегу моря. Один злополучный день перечёркивает всё: его похищают, без объяснений запирают в камере-одиночке, кормят только жареными китайскими пельменями, а через четырнадцать лет выпускают на свободу из большого чемодана в самом центре тайской столицы.",
 "f-wd2850218": "Это история о двух незнакомцах. Два человека могут встретиться где угодно. В нью-йоркском такси в дождливый полдень, в баре по соседству, в очереди у банкомата, в самолете над облаками, глубоко под водой с аквалангом, в эпицентре землетрясения, сидя на лавочке у Тадж-Махала или стоя у подножия Египетских пирамид. Вы можете встретиться при самых обычных обстоятельствах или при весьма экзотических. Акаш и Киара встретились в самой необычной ситуации. Но что, если два человека, случайно встретившись, хотят так и остаться друг другу чужими?",
 "f-wd4754318": "Виджай Кумар, еще будучи ребенком, стал свидетелем жестокого убийства: преступники убили отца и изнасиловали его сестру. У повзрослевшего Виджая была одна лишь цель в жизни – отомстить преступникам. Сестра Виджая работает в полиции, и она уговаривает брата не совершать глупостей. Однажды Виджай и его сестра сталкиваются с Джан Нисаром, который отсидел за преступление, которого не совершал. И теперь они все вместе объединяются ради того, чтобы наказать виновных.",
 "f-wd2614494": "Хозяин крупной торговой фирмы ловит своего управляющего на незаконных финансовых махинациях. Тот, боясь судебного расследования, убивает хозяина. У него остается дочь с двумя маленькими детьми. Она в отчаянии.  Ни мужа (он также погиб при загадочных обстоятельствах), ни отца, никакой опоры. Хитрый управляющий предлагает ей в мужья своего племянника.  Тот, изображая благородного идиота, пытается завладеть миллионным состоянием… Но жестокой будет расплата за все страдания, боль и отчаяние.",
 "f-wd639639": "Шьямал — менеджер по маркетингу в британской фирме в Калькутте, которая занимается производством вентиляторов. Он стремится стать директором фирмы, но его конкурент имеет родственника в совете директоров. Однажды в гости к Шьямалу приезжает Тутул, младшая сестра его жены. Ей нравится Шьямал и она завидует браку сестры с ним. Шьямал показывает ей прелести городской жизни — коктейли, клубы и скачки. Жизнь Шьямала идёт гладко, пока он не узнаёт, что партия вентиляторов, предназначенная для экспорта, неисправна. Есть не так много времени, чтобы устранить неполадки. Эта ситуация может привести к отмене экспортных контрактов и концу его мечте стать директором.",
 "f-wd125808653": "Существует ли идеальная жизнь, в которой есть любовь, брак и дети? Шрия находит это сложной задачей, особенно когда встречает таких мужчин, как Сидхарт, которые считают, что брак ведёт к катастрофе, а дети должны быть запрещены. Времена меняются, отношения развиваются, но идея любви остается неподвластной времени - чем больше вы сопротивляетесь ей, тем сильнее влюбляетесь.",
 "f-wd107304843": "В оживленный торговой центр города Ченнаи врываются террористы и берут посетителей в заложники. Совершенно случайно в этом же молле оказывается крутой шпион, который расправу над злоумышленниками и освобождение сограждан считает делом чести. Торговый центр превращается в зону боевых действий.",
 "f-wd1347849": "Несколько историй из жизни большого города... Смешные и грустные, романтические и реалистичные, ни одна из них не оставит вас равнодушными. Это рассказ о супружеской паре, которые, добившись всех материальных благ, потеряли что-то, что гораздо важнее. Это история о молодом человеке, который поставил всю свою жизнь на карту успеха, но та ли это карта? Это история о двух пожилых людях, когда-то много лет назад они сделали свой выбор, но чтобы было бы, если... Это рассказ о девушке, всю жизнь безуспешно ищущую своего принца, и никак не желающей замечать кого-то, кто уже рядом. А ее подруга своего принца уже нашла, но он женат и совсем не горит желанием что-то менять в своей жизни... Линии судьбы героев фильма пересекаются, рисуя причудливый узор на карте большого города...",
 "f-wd97401953": "Главный герой застрял в колее со своим негативным и одиноким образом жизни и проводит каждый день в комфорте своего одиночества. Щенок по имени Чарли входит в его жизнь и дает ему новый взгляд на нее.",
 "f-wd594033": "В результате удачно проведенной облавы в руки полиции попадает босс наркомафии Чи. Одному из полицейских, Кевину, принимавшему непосредственное участие в аресте, поручают охрану секретарши преступника, которая проходит по делу в качестве главного свидетеля. Но в день суда она исчезает. Только разыскав девушку и арестовав Чи, Кевин сможет снять с себя подозрение в соучастии…",
 "f-wd830874": "Три сестры с детства были неразлучны, но с возрастом отношения их испортились, из любви превратившись в скрытую неприязнь. Однако теперь, когда одна из них на пороге смерти, им снова приходится объединиться и найти что-то общее. Но самым понимающим и внимательным человеком оказывается простая служанка.",
 "f-wd794178": "Господин Бадии решительно собрался уйти из этой жизни и занят отчаянными поисками того, кто мог бы ему в этом помочь. Он уже даже вырыл себе могилу в горах, чтобы его закопали, когда дело будет сделано. Вот только с помощником просто беда: каждый находит какую-нибудь причину для отказа, а то еще и пытается его отговорить. Но слишком тверд в своем намерении господин Бадии.",
 "f-wd117322466": "Проживающая в Лос-Анджелесе богатая семья корейского происхождения узнаёт, что страдает от духа разгневанного предка. Два шамана, эксперт по фэншуй и владелец похоронной фирмы в Корее должны извлечь из могилы гроб с телом прадеда и, не вскрывая, кремировать его как можно быстрее. Однако жадный сотрудник больницы, куда привезли останки на временное хранение, поверив слухам о спрятанных там сокровищах, открывает гроб, что приводит к ужасающим последствиям.",
 "f-wd464651": "Молчание и одиночество - вот ключ к истории двух сестер в вымышленной стране, в несуществующем отеле, в загадочном поезде. Три близких человека - сестры и сын одной из них - скучают, ждут перемен и пытаются услышать хоть что-то сквозь молчание.",
 "f-wd284042": "Прошло несколько лет после катастрофы в Раккун-Сити, но угроза биологического оружия не исчезла. В аэропорту Харвардвилла происходит вспышка Т-вируса, превращающая пассажиров и сотрудников в кровожадных зомби. Леон и Клэр вновь встречаются и оказываются в центре опасного расследования. Пытаясь спасти выживших и остановить распространение вируса, герои обнаруживают следы нового эксперимента, связанного с корпорацией «Амбрелла», и сталкиваются с последствиями её деятельности.",
 "f-wd125563776": "Тегеранского юриста Имана повышают до следователя, а там уже рукой подать до должности судьи и государственной трехкомнатной квартиры. Тут в стране начинаются беспорядки, с утра до ночи приходится штамповать дела, и, поскольку оппозиция размещает в соцсетях личные данные силовиков, Иману выдают табельное оружие. Дочери-старшеклассницы сочувствуют протестующим, даже привыкшая со всем соглашаться жена начинает задавать вопросы, и на фоне семейного кризиса у Имана пропадает пистолет, что грозит тюрьмой уже ему самому.",
 "f-wd815606": "Древний Китай, 208 год нашей эры. Хитроумный премьер-министр, а фактически правитель империи, Цао Цао убеждает нерешительного императора начать войну с двумя независимыми царствами, под предлогом объединения Китая.Милионная армия легко разбивает немногочисленные отряды царства Шу и запирает остатки войска в цитадели у Красной Скалы, не оставив им другого выбора, как обратиться за подмогой к правителю царства Восточный У, послав туда военного советника Чжуге Ляна. Ему удается убедить правителя царства послать армию, возглавляемую вице-правителем Чжоу Юем, на помощь осажденным. И теперь неясно, сможет ли грубая сила одолеть мужество и хитрость…",
 "f-wd19757672": "Мастеру Ип Ману снова приходится использовать вин-чун по прямому назначению, когда бандитская группировка пытается подмять под себя местную школу.",
 "f-wd27964354": "Будущий писатель, его школьная подруга после пластической операции и успешный денди-поджигатель — герои мечутся под тихие звуки саксофона на фоне современной Южной Кореи. Пытаются сжечь прошлое, изо всех сил остаться «нормальными» и не потерять себя.",
 "f-wd37816911": "Испанка Каролина возвращается из Буэнос-Айреса вместе со своим аргентинским мужем и детьми на родину. Однако путешествие оборачивается для женщины и ее близких настоящим потрясением.",
 "f-wd483197": "Одинокий тридцатилетний сеулец-женоненавистник Ли Кан До зарабатывает вымогательством денег у кустарей, задолжавших местному ростовщику. Неплательщиков Кан До калечит, имитируя несчастный случай, чтобы те могли получить страховку и отдать долг. Однажды на пороге его дома появляется женщина, которая называет себя его матерью, бросившей его много лет назад. Подвергнув ее унижениям, Кан До постепенно принимает ее в свой дом. Обретение семьи заставляет его изменить свое отношение к жизни.",
 "f-wd83630": "Энн двадцать три, и у нее две дочери, безработный муж, мать, которая всех ненавидит, и отец, отсидевший последние десять лет за решеткой. Она работает уборщицей в университете, в двери которого и днем она никогда не решилась бы войти.  Ее монотонная жизнь меняется, когда врачи сообщают ей о неизлечимой болезни, и что ей осталось жить всего два-три месяца. Энн решает радикально изменить свою жизнь.",
 "f-wd666017": "В 1945 году молодой немец Леопольд Кесслер считал, что война закончилась, и приехал из Америки в оккупированную союзниками Германию с самыми лучшими намерениями. Он устроился работать проводником в железнодорожной компании и думал, что теперь жизнь пойдет как по рельсам…",
 "f-wd784465": "Ян Розенберг — композитор и руководитель симфонического оркестра, а его жена Ева — скрипачка. У Яна болезнь сердца, и врач рекомендовал супругам поселиться на острове в Балтийском море. Тем временем, начинается война, которая затрагивает супругов, и их спокойной жизни настаёт конец.",
 "f-wd19806501": "Отец трёх дочерей Сати, Ёсино и Тики ушёл к другой женщине, когда они были ещё совсем детьми. Мать, не вынеся измены отца, тоже их бросила. Старшей сестре Сати ничего не оставалось, кроме как стать главой оставшейся семьи и заботиться о младших, хотя она сама тогда ещё училась в школе. Через 14 лет их отец умирает, и три сестры приезжают на похороны. Там они знакомятся со своей единокровной сестрой — 13-летней Судзу. Мать Судзу давно умерла, и после смерти отца та остаётся с мачехой и неродным братом. Сёстры предлагают Судзу переехать жить к ним.",
 "f-wd483780": "Уважаемый и любимый прихожанами священник добровольно соглашается на медицинский эксперимент, в результате которого он непредвиденно становится вампиром. Физические и психологические изменения приводят к тому, что герой вступает в порочную связь с уставшей от рутинной жизни женой лучшего друга. С каждым днем вампиру-священнику все труднее сохранять в себе что-то человеческое…",
 "f-wd1165090": "Поздно вечером в своей квартире застрелены журналист и его подруга — люди, изучавшие каналы поставки в Швецию секс-рабынь из Восточной Европы. Среди клиентов малопочтенного бизнеса замечены представители властных структур. Кажется очевидным, каким кругам была выгодна смерть этих двоих. Микаэл Блумквист начинает собственное расследование гибели своих коллег и друзей и вдруг узнает, что в убийстве подозревают его давнюю знакомую Лисбет Саландер, самую странную девушку на свете, склонную играть с огнем — к примеру, заливать его бензином.",
 "f-wd1514098": "Гениальный ученый Шурагами создал супер организм Биорант, используя для этого радиоактивные клетки Годзиллы, за которыми охотится международная мафия. А в это время извержение вулкана возродило спящего на дне Токийского залива Годзиллу к жизни. Жители Япония в панике — встреча двух монстров неизбежна и выживет только один из них. И на этот случай силы обороны приготовили своё новое оружие «Супер Икс-2», с помощью которого они готовы уничтожить уцелевшего монстра.",
 "f-wd1253821": "Гертруда могла бы быть абсолютно счастлива. Богатый и верный муж; молодой и талантливый любовник; друг юности, который до сих пор питает к ней чувства - каждый любит ее по-своему. Но Гертруде всё это уже ни к чему, она больше не нуждается в любви, постепенно теряя вместе с ней и вкус к жизни.",
 "f-wd3019162": "TPB-AFK, документальный фильм о The Pirate Bay и его основателях. Фильм создавался в течение 5-ти лет и рассказывает о жизни трех основателей Пиратской Бухты и судебном процессе по их делу в Швеции.  Пиратская Бухта в лице ее основателей на протяжении нескольких лет является ответчиком в многочисленных судебных процессах, а режиссёр Саймон Клозе задокументировал процесс борьбы правообладателей и владельцев TPB.",
 "f-wd2301516": "Однажды вечером в Стокгольме начинает происходить ряд невероятно странных, не связанных друг с другом событий. Немолодой клерк сходит с ума после безжалостного увольнения с работы… На улице жестоко избивают заблудившегося эмигранта… Фокусник совершает роковую ошибку прямо во время своего представления, по-настоящему распилив несчастного добровольца из публики… Растерянного человека, в отчаянии спалившего дотла свой мебельный магазин, преследует призрак удавленника… Огромная толпа важных и мрачных взрослых людей приносит в жертву невинную девочку… В городе немыслимые пробки; по улицам чинно ходят хорошо одетые чиновники, хлещущие себя плетьми… Похоже, пришел тот час, которого все так давно боялись…",
 "f-wd1284313": "Планета Земля решает отомстить людям за неправильное отношение к природе и насылает на них злобного монстра Баттру. Единственное спасение от него — гигантская бабочка Мотра, но она давно спит, и её нужно разбудить. К тому же есть ещё и Годзилла, и никто не знает, чью сторону он примет в этой битве.",
 "f-wd60794": "Знаменитый мастер восточных единоборств Джеки Чан вновь демонстрирует свою непревзойденную технику и виртуозные трюки в этом великолепном романтическом боевике. Несравненная Бу, девушка из маленькой деревни на берегу океана, приезжает в шумный Гон Конг в поисках приключений. Здесь она знакомиться с Ченом — знаменитым миллионером. Но романтическая Золушка не подозревает что Чен окажется очень опасным кавалером.",
 "f-wd1217263": "Почти наши дни. Одно из государств Латинской Америки. Социальные катаклизмы, восстания, нищета, перемены, но традиционные религиозные устои незыблемы. Молодой падре Амаро, недавно принявший сан, нарушает строгие правила, влюбившись в молодую прихожанку.",
 "f-wd113450389": "Адвокат и прокурор подают в суд на власти Аргентины, обвиняя их в преступлениях против граждан.",
 "f-wd1299823": "История женщины, проданной в качестве жены богатому китайскому сельчанину в 20-х гг XX века.",
 "f-wd1768462": "К концу 20-го столетия японцам удалось создать электронную систему слежения за Годзиллой, что не спасало от нашествия монстра, зато, по крайней мере, давало людям возможность знать, куда в очередной раз направляется «верзилла».  Однажды в результате нападения Годзиллы не только был разрушен целый город, но и своим огненным дыханием монстр расколол скалу, возраст которой насчитывал не один десяток миллионов лет.  Расколовшаяся скала высвободила летающую тарелку, которая спустя некоторое время трансформировалась в гигантское чудовище инопланетного происхождения. Наступил день, когда в решающей битве сошлись Годзилла и Орга…",
 "f-wd880396": "Главный герой решается на отчаянный шаг. Путем сложнейшей хирургической операции он становится невосприимчив к боли. Кто он теперь? Мститель, не знающий пощады?  Теперь его лицо скрывает таинственная черная маска, приводящая врагов в состояние панического ужаса. Какая тайна скрывается за ней? Ответ могут дать только мертвые. Но мертвые не спешат выдавать свои секреты. А Черная Маска вновь вершит свой суд…",
 "f-wd259831": "Упустившая свой поезд Магги встречает Давида и проводит вместе с ним ночь. Не имея денег на проживание, они проникают в летний домик, хозяин которого предлагает им сделку. Там им предстоит столкнуться со своим прошлым, настоящим и туманным будущим.",
 "f-wd1078811": "Ракель, Марта, Карин и Аннетт замужем за четырьмя братьями. Ожидая своих супругов в летнем коттедже, каждая из них рассказывает свою историю.",
 "f-wd59707291": "Счастливая женщина Вера с мужем и маленькой дочкой переезжает в новый дом. А там во время сильной грозы происходит смещение временных пластов, в результате чего женщина пытается спасти от гибели мальчика, жившего тут 25 лет назад. Но этот акт доброй воли приводит к тому, что Вера оказывается в изменённом настоящем, в котором супруг её не знает, и её собственная дочь не родилась.",
 "f-wd2131368": "Как это бывает каждые два года, пришло время старейшинам самой древней Гонконгской триады «Во Шинг» выбрать нового главу. Между двумя приемлемыми кандидатами возникает страшная конкуренция.  Лок — фаворит в выборах, так как он находится на хорошем счету у старейшин. Однако его соперник, Большой Ди, не остановится ни перед чем, чтобы изменить ситуацию в свою пользу. Он даже готов пойти против многовековых традиций триады и попытаться повлиять на окончательное решение с помощью денег и насилия.  Когда пропадает давний символ власти «Во Шинг» — жезл «Голова Дракона» — начинается беспощадная битва за власть, и стремление соперничающих лагерей поскорее вернуть жезл, грозит триаде расколом.",
 "f-wd1199756": "Киноадаптация знаменитой японской манги. Работающий на правительство вампир командирован в спецшколу и обнаруживает, что один из учеников — замаскированный демон.",
 "f-wd51998716": "Во времена «золотых лет» марихуаны, в то самое десятилетие, когда в Колумбии зародилась и расцвела наркоторговля, местные жители Рапайет и его семья оказываются втянутыми в войну за контроль над бизнесом, который в конце концов уничтожит их жизнь и их культуру.",
 "f-wd964843": "Шведская парочка геев решает усыновить ребёнка, но вместо ожидаемого 15-месячного младенца в их доме по ошибке оказывается 15-летний подросток-хулиган.",
 "f-wd1341843": "Пол влюбился в девушку, но ее родители запрещают им встречаться. У Пола — шизофрения, он попадает в психиатрическую лечебницу. Будучи наделен талантами художника и поэта. Он отождествляет себя с героями Шекспира и Ван Гогом.  Друзья Пола по клинике — Оли, у которого телепатический контакт с «Битлз» и эрудит Виктор, которому временами кажется, что он — Гитлер.  Пытаясь скрасить ужас холодной исландской жизни, троица время от времени сбегает из больницы и наведывается то в гости к президенту, то в самый фешенебельный ресторан Рейкьявика.",
 "f-wd586410": "Альтернативный вариант событий аниме-сериала «Драконий жемчуг», описывающий знакомство Гоку с Бульмой, Улонгом, Ямчой и Мастером Роши, а также изменённую историю армии Красной Ленты.",
 "f-wd664983": "Чтобы сражаться с Годзиллой, японские ученые сконструировали два новых вида оружия — высокотехнологичный корабль Грифон и устройство «Приливная волна». Испытание «Приливной волны» совпадает по времени с появлением Мегануронов — стрекозообразных существ, которые питаются энергией человека.  Королева Мегагирус, повелительница Мегануронов, монстр высотой метров в 60, готовится напасть на Годзиллу, чтобы поглотить ее энергию. Люди здесь, может показаться, совсем ни при чем, однако от исхода битвы двух супергигантов зависит судьба человечества…",
 "f-wd88465322": "Сэм, сирийский беженец, чьё тело было превращено в живое произведение искусства и выставлено в музее, скоро поймет, что продал не только свою кожу.",
 "f-wd289014": "Очарованный проходящей мимо красивой девушкой молодой бандит пытается овладеть ею, но получив отпор, берется за исполнение своего странного и шокирующего плана. И через несколько дней девушка оказывается в «квартале красных фонарей», но не в качестве прохожей, а вынужденная торговать своим телом.",
 "f-wd484709": "Монарх порабощенного Юаньской империей государства Корё выбрал и воспитал мальчиков для личной стражи, названной Конрёнве. С позволения короля стражники жили во дворце, и всегда охраняли своего господина. Глава стражи, Хон Рим, пользовался особой благосклонностью короля, чем вызывал у королевы обиду и ревность. Тем временем, отношения между Корё и Юанью обострились. Император Юани, под предлогом отсутствия у трона Корё законного наследника, потребовал назначить наследным принцем двоюродного брата короля — Кёнвона. Король, невзирая на недовольство высокопоставленных чиновников, отверг это требование. Будучи неспособным на соитие с женщиной, он втайне повелел своему любовнику, Хон Риму, спать с королевой, дабы та смогла зачать дитя, которое позволило бы королю сохранить власть.",
 "f-wd357379": "Сабата, лучший стрелок дикого запада, помогает мексиканским повстанцам украсть повозку с золотом, на которое революционеры планируют купить оружие. Однако на это золото уже успела позариться и местная бандитская шайка.",
 "f-wd1180275": "Дружба и любовь в мире проституции в Мадриде.",
 "f-wd3084243": "Во времена правления династии Мин Император учредил секретную службу безопасности, которая подчинялась только его указам, Цзиньивэй, или Охрана в парчовых халатах. Члены этого органа наделялись самыми широкими полномочиями и действовали исключительно в интересах главы государства. Неподсудны. Безжалостны. Непобедимы.  Действие фильма разворачивается на закате династии Мин, когда службой управляли евнухи. В изгнании томится принц Чин, вынашивая план отмщения. На удачу он сумел переманить на свою сторону главного евнуха Цзя Цзин Чжона, и тот отдает императорский приказ главе Цзиньивэй — Чин Лону — схватить Советника Чжао Шэнь Еня и забрать его шкатулку якобы со списком предателей. Да вот беда, там хранилась Императорская печать, символ власти, которую следует оберегать как зеницу ока. И Чин Лон осознал, что его здорово подставили. Избегая ловушек, он пытается выяснить правду, но век члена Цзиньивэя недолог, смерть бежит по пятам, выполнит ли Чин Лон свое последнее задание?",
 "f-wd1152489": "В какой-то период жизни Негиши Соичи что-то пошло не так. Любитель поп-музыки и талантливый гитарист неведомыми путями судьбы стал лидером японской дэд-метал группы «DMC». Но он не отчаивается и пытается изменить свою жизнь любыми способами… Вот только получается всё совсем наоборот…",
 "f-wd485782": "Пока город существует в своем привычном ночном ритме, молодая девушка кончает жизнь самоубийством, спрыгнув с высоты прямо на мостовую. А ранее престарелая дама нанимает ее в богатый дом, где они вместе будут прислуживать семье, состоящей из мужа, беременной двойней жены и развитого не по годам ребенка. Поначалу все идет замечательно, новая работница вписывается в семью без малейших проблем, пока пристальный интерес к ней не начинает испытывать хозяин дома.",
 "f-wd703857": "Фильм «Троецарствие» повествует об удивительной судьбе простого китайского воина, ставшего величайшим полководцем в эпоху Троецарствия. Это время (220—280 гг.), наступившее после распада великого единого государства, созданного императором Цинь Ши-Хуанди, было наполнено войнами и сражениями войск трех царств — Шу, У и Вэй.  Молодой парень по имени Цзылон вступает в ряды воинов Шу и отправляется на войну. Там он совершает невероятные подвиги и показывает выдающееся умение сражаться всеми видами холодного оружия. После того, как ему удается спасти царского сына, герой быстро делает карьеру и становится полководцем. А затем двадцать лет проводит в непрерывных сражениях, в которых завоевывает прозвище «Непобедимый генерал».",
 "f-wd7444445": "Три красивых северокорейских шпиона из элитного отряда спецназа («отряд 5446») отправлены в Южную Корею с якобы высокой целью объединения Кореи. Эти амбициозные парни должны жить как нормальные люди в ожидании сигнала начала их тайной миссии. Всем троим приходится жить в бедном районе Сеула. Прошло два года и, не получая никаких распоряжений от Севера, парни постепенно привыкают к жизни в Южной Корее. Внезапно, они получают сигнал начать их тайную миссию. Между тем, инструктор северокорейской армии Ким Тхэ Вон пересекает границу, чтобы устранить тех, кто отказывается выполнять приказы северокорейского правительства…",
 "f-wd1195466": "В стокгольмском госпитале Саббатсберг жестоко убит пациент. Следователи Бек и Рённ расследуют дело, которое оказывается сложнее, чем они думали. Убитый - комиссар полиции - имел плохую репутацию из-за того, что истязал задержанных и издевался над подчинёнными. Но кто из обиженных им людей мог пойти на убийство? Расследуя преступление, Бек узнаёт о давней трагедии, которая стала причиной цепи событий, приведшей к убийству, и понимает, что его жизнь и жизни его коллег в смертельной опасности. А в это время, совсем рядом, вооружённый до зубов человек уже карабкается на крышу высотного здания...",
 "f-wd2301945": "Джулия уже не первый год работает агентом по продаже недвижимости и стала настоящим профессионалом своего дела. Однажды в квартире, в которой умер арендатор, она находит большую сумму денег, после чего решает любой ценой завладеть ими. Однако сделать это будет очень непросто, поскольку ей придется столкнуться с гневом достаточно необычного общества соседей, которым руководит администратор дома. Но женщина не собирается так просто сдаваться и готова пойти на любые ухищрения, чтобы добиться желаемого результата. С этого момента ее ждет настоящая война, одержать победу в которой будет очень непросто ...",
 "f-wd137984": "1582 год. Великий Ода Нобунага пал от руки своего некогда верного вассала Мицухидэ Акечи. Но и его судьба была предрешена — Тойотоми Хидэёси взял власть в стране в свои руки. Он провёл чёткую грань между самураями и крестьянами, в результате чего пропасть между богатыми и бедными стала как никогда шире. Но 15 лет спустя в стране появился человек, который встал на защиту крестьян в неравной борьбе с правительством. Этим человеком стал великий ниндзя Исикава Гоемон. Тайны прошлой жизни свели его с другим не менее легендарным ниндзя — Киригакурэ Сайзо. Кто же победит в этой борьбе?",
 "f-wd129657": "… Темнота. Ты умер, и ты воскрес в странной комнате, где есть черный глянцевый шар и множество других людей, умерших, как и ты, совсем недавно. И тут возникает очень правильный вопрос — что происходит? Вряд ли это имеет какое-либо отношение к религии, это не ад, не чистилище и вот уж точно не рай. Обычная комната в отеле с обшарпанными стенами и приятным видом на Токио из окна. Обычная комната, не считая того, что единственная мебель в ней — это огромный черный шар. Но это мелочь по сравнению с тем, что хотя твои пальцы проходят сквозь ручку двери, ты не можешь её открыть. Нет, ты не призрак, твое сердце бьется, ты дышишь и даже очень неплохо себя чувствуешь для человека, которого пару минут назад сбил поезд. Что же ждет тебя дальше?",
 "f-wd1141588": "2077 год. 10 лет назад Япония вышла из ООН и отгородилась от мира магнитным полем. Поводом для этого послужила резолюция ООН, которая запретила дальнейшее развитие робототехники и биотехнологий, угрожающих существованию человечества. Правительство США посылает в Японию спецподразделение SWORD под командованием женщины по имени Вексилл. Задание — узнать, что за 10 лет случилось в Японии, где запрещённые науки развивались абсолютно бесконтрольно.",
 "f-wd2706861": "Томе родилась в 1918 году и почти сразу же началась ее жестокая жизнь секс-рабыни. Она подозревает, что даже ее собственный отец сожительствовал с ней. Вскоре у нее рождается дочь Нобуко. Наконец, в 23 года ей удается выйти замуж, но ненадолго — от ее мужа беременеет служанка. Вскоре Томе попадает в тайный публичный дом и со временем становится его хозяйкой.",
 "f-wd29385180": "После семейного скандала Наруми Касэ забирает мужа от доктора. Тот кажется совершенно другим человеком — тихим, спокойным и слегка дезориентированным. В это же время в округе происходит жестокое убийство семьи, подозревают дочь семейства. Репортер Сакурай отправляется на место происшествия и там встречает странного молодого человека, который ищет подозреваемую и просит журналиста стать его проводником в мире людей.",
 "f-wd867713": "У полицейских возникли проблемы: их прежний «стукач» был вычислен мафией и убит. Нового агента найти нелегко, и тогда вспоминают о бывшем отчаянном полицейском Ко Чоу…"
};
